import React from 'react';
import { Container, Row, Col } from 'reactstrap';
import SidebarFilters from './SidebarFilters'; // adjust the path if needed
import DoctorCard from './DoctorCard';       // adjust the path if needed

const DoctorsPage = () => {
  return (
    <Container fluid className="mt-4">
      <Row className="m-3">
        <Col md="3">
          <SidebarFilters />
        </Col>
        <Col md="9">
          <DoctorCard />
        </Col>
      </Row>
    </Container>
  );
};

export default DoctorsPage;
